  S: { name: "Phase (S)", symbol: "S", matrix: [[{ re: 1, im: 0 }, { re: 0, im: 0 }], [{ re: 0, im: 0 }, { re: 0, im: 1 }]], description: "S phase gate (π/2 rotation)" },
