export function getQuantumState(): QuantumState {
  const qubitArray = Array.from(qubits.values());
  const coherenceAvg = qubitArray.length > 0 ? qubitArray.reduce((s, q) => s + complexMag(q.alpha), 0) / qubitArray.length : 0;
